    window.__ss.q('.jfss-group-root > .jfss-group-add .jfss-add-rule').click();
    A.fire(A.last().querySelector('.jfss-rule-field'), spec.field);
    if (A.last().querySelector('.jfss-rule-field').value !== spec.field) throw new Error('no field ' + spec.field);
    A.fire(A.last().querySelector('.jfss-rule-op'), spec.op);
    const r = A.last();
    if (spec.value !== undefined) A.fire(r.querySelector('.jfss-rule-input.jfss-rule-value, .jfss-picker-single .jfss-picker-input'), String(spec.value));
    if (spec.from !== undefined) A.fire(r.querySelector('.jfss-rule-from'), String(spec.from));
    if (spec.to !== undefined) A.fire(r.querySelector('.jfss-rule-to'), String(spec.to));
    if (spec.amount !== undefined) A.fire(r.querySelector('.jfss-rule-amount'), String(spec.amount));
    if (spec.unit !== undefined) A.fire(r.querySelector('.jfss-rule-unit'), spec.unit);
    if (spec.bool !== undefined) A.fire(r.querySelector('.jfss-rule-bool'), String(spec.bool));
    if (spec.provider !== undefined) A.fire(r.querySelector('.jfss-rule-provider'), spec.provider);
    if (spec.orig) { const box = r.querySelector('.jfss-rule-original'); box.checked = true; box.dispatchEvent(new Event('change', { bubbles: true })); }
    for (const label of spec.choices || []) { const b = [...r.querySelectorAll('.jfss-choice')].find(x => x.textContent === label); if (!b) throw new Error('no choice ' + label); b.click(); }
    for (const text of spec.typed || []) { const input = r.querySelector('.jfss-picker-input'); input.focus(); input.value = String(text); input.dispatchEvent(new Event('input', { bubbles: true })); input.dispatchEvent(new KeyboardEvent('keydown', { key: 'Enter', bubbles: true, cancelable: true })); }
    if (spec.series) {
      const input = r.querySelector('.jfss-picker-input'); input.focus(); input.value = spec.series; input.dispatchEvent(new Event('input', { bubbles: true }));
      const s = await A.until(() => [...r.querySelectorAll('.jfss-suggestion')].find(x => x.textContent.indexOf(spec.pick) === 0));
      s.click();
    }
    return true;
  },
  search: async () => {
    const before = performance.getEntriesByType('resource').filter(e => /SmartSearch\/Search$/.test(e.name)).length;
    window.__ss.q('.jfss-search-button').click();
    const note = window.__ss.q('.jfss-form-error');
    await window.__adv.until(() => (note && note.textContent) || (performance.getEntriesByType('resource').filter(e => /SmartSearch\/Search$/.test(e.name)).length > before && window.__ss.done()));
    await window.__adv.sleep(150);
    return { ids: window.__ss.norm(window.__ss.ids()), error: note ? note.textContent : '', count: (window.__ss.q('.jfss-count') || {}).textContent || '', notice: (window.__ss.q('.jfss-notices') || {}).textContent || '' };
  },
  // The user's items as core /Items gives them, with the facts the oracles read.
  items: async () => {
    const uid = ApiClient.getCurrentUserId();
    const fields = 'Path,Overview,OriginalTitle,DateCreated,PremiereDate,Genres,Tags,Studios,OfficialRating,ProviderIds,MediaSources,ParentId,ProductionYear,Settings';
    const all = (await ApiClient.getItems(uid, { Recursive: true, IncludeItemTypes: 'Movie,Series,Episode,MusicVideo,Video,BoxSet', Fields: fields, EnableUserData: true, IsMissing: false, Limit: 2000 })).Items;
    const libs = (await window.__ss.api('GET', 'SmartSearch/Libraries')).body;
    const byLib = {};
    for (const l of libs) { byLib[l.Name] = new Set((await ApiClient.getItems(uid, { Recursive: true, ParentId: l.Id, IncludeItemTypes: 'Movie,Series,Episode,MusicVideo,Video,BoxSet', Limit: 2000 })).Items.map(i => window.__ss.norm([i.Id]))); }
    const ended = new Set((await ApiClient.getItems(uid, { Recursive: true, IncludeItemTypes: 'Series', SeriesStatus: 'Ended' })).Items.map(i => window.__ss.norm([i.Id])));
    return { all, byLib, ended, now: Date.now() };
  },
  fold: (t) => String(t || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase(),
  source: (i) => (i.MediaSources || [])[0] || {},
  width: (i) => { const v = (window.__adv.source(i).MediaStreams || []).find(s => s.Type === 'Video'); return v ? v.Width || 0 : 0; },
  res: (w) => w >= 3800 ? '2160p' : w >= 2500 ? '1440p' : w >= 1900 ? '1080p' : w >= 1200 ? '720p' : w > 0 ? 'SD' : 'Unknown',
  minutes: (i) => i.RunTimeTicks > 0 ? Math.max(1, Math.round(i.RunTimeTicks / 6e8)) : null,
  pid: (i, p) => { const ids = i.ProviderIds || {}; const k = Object.keys(ids).find(x => x.toLowerCase() === p.toLowerCase()); return k ? ids[k] : ''; },
  // Every field: a rule built in the editor, the kinds searched, and what /Items says it should find.
  cases: () => {
    const A = window.__adv;
    const MEV = ['Movie', 'Episode', 'Video'];
    return [
      { name: 'Title contains, accents ignored', kinds: ['Movie'], spec: { field: 'Title', op: 'Contains', value: 'amelie' }, want: (i) => A.fold(i.Name).includes('amelie') },
      { name: 'Title contains, original title too', kinds: ['Movie'], spec: { field: 'Title', op: 'Contains', value: 'wc original', orig: true }, want: (i) => A.fold(i.Name).includes('wc original') || A.fold(i.OriginalTitle).includes('wc original') },
      { name: 'Original title is not empty', kinds: ['Movie'], spec: { field: 'OriginalTitle', op: 'IsNotEmpty' }, want: (i) => !!i.OriginalTitle },
      { name: 'Overview contains', kinds: ['Movie'], spec: { field: 'Overview', op: 'Contains', value: 'synthetic' }, want: (i) => A.fold(i.Overview).includes('synthetic') },
      { name: 'Series name starts with', kinds: ['Episode'], spec: { field: 'SeriesName', op: 'StartsWith', value: 'test' }, want: (i) => A.fold(i.SeriesName).startsWith('test') },
      { name: 'Series is any of (the show picker)', kinds: ['Episode'], spec: { field: 'Series', op: 'AnyOf', series: 'test', pick: 'Test Series' }, want: (i) => A.fold(i.SeriesName).startsWith('test series') },
      { name: 'Path contains (administrators)', admin: true, kinds: ['Movie'], spec: { field: 'Path', op: 'Contains', value: 'Movies 2' }, want: (i) => A.fold(i.Path).includes('movies 2') },
      { name: 'Year between', kinds: ['Movie', 'Series'], spec: { field: 'Year', op: 'Between', from: 2001, to: 2010 }, want: (i) => i.ProductionYear >= 2001 && i.ProductionYear <= 2010 },
      { name: 'Year is any of (typed)', kinds: ['Movie'], spec: { field: 'Year', op: 'AnyOf', typed: [2001, 2020] }, want: (i) => i.ProductionYear === 2001 || i.ProductionYear === 2020 },
      { name: 'Release date before', kinds: ['Movie'], spec: { field: 'PremiereDate', op: 'Before', value: '2000-01-01' }, want: (i) => !!i.PremiereDate && Date.parse(i.PremiereDate) < Date.parse('2000-01-01T00:00:00Z') },
      { name: 'Date added after', kinds: MEV.concat(['Series']), spec: { field: 'DateAdded', op: 'After', value: '2026-11-05' }, want: (i) => Date.parse(i.DateCreated) >= Date.parse('2026-11-06T00:00:00Z') },
      { name: 'Date added in the last 3650 days', kinds: MEV, spec: { field: 'DateAdded', op: 'InLast', amount: 3650, unit: 'Days' }, want: (i, c) => Date.parse(i.DateCreated) >= c.now - 3650 * 864e5 },
      { name: 'Library is any of', kinds: ['Movie'], spec: { field: 'Library', op: 'AnyOf', choices: ['Movies'] }, want: (i, c) => c.byLib.Movies.has(window.__ss.norm([i.Id])) },
      { name: 'Item type is none of', kinds: MEV.concat(['Series']), spec: { field: 'ItemType', op: 'NoneOf', choices: ['Episode'] }, want: (i) => i.Type !== 'Episode' },
      { name: 'Genres has any of', kinds: ['Movie'], spec: { field: 'Genres', op: 'AnyOf', typed: ['Science Fiction'] }, want: (i) => (i.Genres || []).some(g => A.fold(g) === 'science fiction') },
      { name: 'Tags has all of', kinds: ['Movie'], spec: { field: 'Tags', op: 'AllOf', typed: ['wc-noir', 'wc-classic'] }, want: (i) => ['wc-noir', 'wc-classic'].every(t => (i.Tags || []).some(x => A.fold(x) === t)) },
      { name: 'Studios has none of', kinds: ['Movie'], spec: { field: 'Studios', op: 'NoneOf', typed: ['WC Studio'] }, want: (i) => !(i.Studios || []).some(s => A.fold(s.Name) === 'wc studio') },
      { name: 'Parental rating is any of', kinds: ['Movie'], spec: { field: 'OfficialRating', op: 'AnyOf', typed: ['R'] }, want: (i) => i.OfficialRating === 'R' },
      { name: 'Show status is any of', kinds: ['Series'], spec: { field: 'SeriesStatus', op: 'AnyOf', choices: ['Ended'] }, want: (i, c) => c.ended.has(window.__ss.norm([i.Id])) },
      { name: 'Community rating at least', kinds: ['Movie'], spec: { field: 'CommunityRating', op: 'Ge', value: 7 }, want: (i) => i.CommunityRating >= 7 },
      { name: 'Critic rating is not empty', kinds: ['Movie'], spec: { field: 'CriticRating', op: 'IsNotEmpty' }, want: (i) => typeof i.CriticRating === 'number' },
      { name: 'Runtime at least', kinds: MEV, spec: { field: 'Runtime', op: 'Ge', value: 2 }, want: (i) => A.minutes(i) >= 2 },
      { name: 'Resolution is any of', kinds: MEV, spec: { field: 'Resolution', op: 'AnyOf', choices: ['720p', '1080p'] }, want: (i) => ['720p', '1080p'].includes(A.res(A.width(i))) },
      { name: 'Container is any of', kinds: MEV, spec: { field: 'Container', op: 'AnyOf', typed: ['mp4'] }, want: (i) => String(i.Container || '').toLowerCase().split(',').includes('mp4') },
      { name: 'Video type is any of', kinds: MEV, spec: { field: 'VideoType', op: 'AnyOf', choices: ['Video file'] }, want: (i) => i.VideoType === 'VideoFile' },
      { name: '3D is no', kinds: MEV, spec: { field: 'Is3D', op: 'Is', bool: false }, want: (i) => !i.Video3DFormat },
      { name: 'File size more than', kinds: MEV, spec: { field: 'FileSize', op: 'Gt', value: 0.003 }, want: (i) => (A.source(i).Size || 0) > 0.003 * 1073741824 },
      { name: 'Bitrate more than', kinds: MEV, spec: { field: 'Bitrate', op: 'Gt', value: 0.8 }, want: (i) => (A.source(i).Bitrate || 0) > 0.8e6 },
      { name: 'Played is yes', kinds: MEV, spec: { field: 'Played', op: 'Is', bool: true }, want: (i) => !!(i.UserData && i.UserData.Played) },
      { name: 'Favorite is yes', kinds: MEV.concat(['Series']), spec: { field: 'Favorite', op: 'Is', bool: true }, want: (i) => !!(i.UserData && i.UserData.IsFavorite) },
      { name: 'In progress is yes', kinds: MEV, spec: { field: 'InProgress', op: 'Is', bool: true }, want: (i) => !!(i.UserData && i.UserData.PlaybackPositionTicks > 0) },
      { name: 'Play count at least', kinds: MEV, spec: { field: 'PlayCount', op: 'Ge', value: 1 }, want: (i) => !!(i.UserData && i.UserData.PlayCount >= 1) },
      { name: 'Last played in the last 30 days', kinds: MEV, spec: { field: 'LastPlayed', op: 'InLast', amount: 30, unit: 'Days' }, want: (i, c) => !!(i.UserData && i.UserData.LastPlayedDate && Date.parse(i.UserData.LastPlayedDate) >= c.now - 30 * 864e5) },
      { name: 'Has an IMDb id', kinds: ['Movie', 'Series', 'Episode'], spec: { field: 'HasProviderId', op: 'Is', bool: true, provider: 'Imdb' }, want: (i) => !!A.pid(i, 'Imdb') },
      { name: 'Provider id is', kinds: ['Movie'], spec: { field: 'ProviderId', op: 'Eq', value: 'tt9005010', provider: 'Imdb' }, want: (i) => A.pid(i, 'Imdb') === 'tt9005010' },
      { name: 'Locked is yes', kinds: ['Movie', 'Series'], spec: { field: 'Locked', op: 'Is', bool: true }, want: (i) => i.LockData === true }
    ];
  },
  // Each case: Reset, the kinds, the rule built, Search; its results against the oracle's over the same user's items.
  runAll: async (isAdmin) => {
    const A = window.__adv;
    const ctx = await A.items();
    const out = [];
    for (const c of A.cases()) {
      if (c.admin && !isAdmin) continue;
      window.__ss.q('.jfss-reset').click();
      await A.sleep(50);
      A.kinds(c.kinds);
      let error = '';
      try { await A.build(c.spec); } catch (e) { error = String(e && e.message || e); }
      const got = error ? { ids: '', error } : await A.search();
      const server = window.__ss.norm(ctx.all.filter(i => c.kinds.includes(i.Type) && c.want(i, ctx)).map(i => i.Id));
      const n = server ? server.split(',').length : 0;
      out.push({ name: c.name, ok: !got.error && got.ids === server, found: got.ids ? got.ids.split(',').length : 0, expected: n, error: got.error, notice: got.notice });
    }
    return out;
  }
};

